  'superviseConsent.allSetTitle': { en: "You're all set", zh: '一切就绪', th: 'พร้อมแล้ว', ru: 'Всё готово', fr: 'Vous êtes prêt' },
  'superviseConsent.allSetSubtitle': { en: 'No drop-off consent needed — our team is finishing your check-in now.', zh: '无需签署托管同意书——我们的团队正在为您完成登记。', th: 'ไม่ต้องยินยอมสำหรับการฝากดูแล — ทีมงานของเรากำลังทำการเช็คอินให้คุณ', ru: 'Согласие на высадку не требуется — наша команда завершает вашу регистрацию.', fr: "Aucun consentement de dépose requis — notre équipe finalise votre enregistrement." },

