const FALLBACK: SupportedLang = 'en';

export function lookup(key: string, lang: SupportedLang): string | undefined {
  const entry = DICTIONARY[key];
  if (!entry) return undefined;
  return entry[lang] ?? entry[FALLBACK];
}
